-- World fixes: Andorhal, the two battles (Western Plaguelands), 2026-11-20
-- Four: Andorhal Defenders stand next to undead without fighting, and the same for the farmers (Provincial
-- Minutemen) next to an Opengut Behemoth in the fields. Asked whether Andorhal should be phased.
-- Found: Andorhal has two battles, one after the other, and our dump shows both at once with no phases.
--   First battle (quests Scourge First..., War Machines, The Endless Flow, Scholomancer, Brute Strength):
--     Alliance (Andorhal Defender 44328) and Horde (Andorhal Deathguard 44326/44447) each fight the Scourge
--     (Desiccated Magus 44315, Desiccated Spearman 44316, Opengut Behemoth 44562). TDB 8.3.7 has exactly this
--     battle: 181 spawns, every Defender and Deathguard 44326 standing within 5 yards of a Desiccated.
--     Ours had only 31 of them (2 Behemoths for War Machines, which needs 6 kills).
--   Second battle (after The Battle Resumes!: Supporting the Troops, Ashes to Ashes, The Farmers' Militia,
--     Val'kyr Incursion, Brother Against Brother, Aradne): Alliance and the farmers' militia against
--     the Forsaken and their val'kyr. TDB 8.3.7 has none of it; ours has all of it (all quest targets, kept).
--   The Desiccated templates also carried UNIT_FLAG_IMMUNE_TO_NPC (0x200), which TDB 8.3.7 does not, so no
--   soldier could ever hit them. The Scourge's faction (974) is neutral to both armies: they only fight
--   soldiers that attack them, so the soldiers need a starter (staged-npc-battles pattern).
-- Changed (the split and the switch quests are our own reading of the quest text; 8.3.7 data has no phases here):
--   phase 314: the first battle, 1:1 with TDB 8.3.7, plus our Stickbone Berserkers (The Endless Flow; TDB has none)
--   phase 317: the second battle, our dump's spawns, unchanged except the phase
--   A player is in phase 317 once The Battle Resumes! (27083 Horde, 27197 Alliance) or any second-battle quest
--   is taken, completed or rewarded, otherwise in phase 314. Everyone also keeps phase 169 (normal spawns).
--   Quest givers (Koltira, Thassarian, Jearl Donald, Lindsay Ravensun, Lang Loosegrip), the fires, the towers
--   and the Scourge Invasion event spawns are not phased.
-- Phases 314 and 317 exist in Phase.db2 and are used nowhere else here. Needs tools/bfa/staged-npc-battles.patch.
-- Run after 2026_11_17_44. Safe to run twice.

-- 1. Templates as in TDB 8.3.7: no IMMUNE_TO_NPC on the Desiccated and on the two second-battle commanders
UPDATE `creature_template` SET `unit_flags`=`unit_flags`&~0x200 WHERE `entry` IN (44315,44316,44449,44450);
-- Staged-battle flag (our own tuning, as in 2026_11_17_44): NPC damage stops at 85% health, players deal full damage
-- First battle: Andorhal Defender 44328, Andorhal Deathguard 44326, Andorhal Deathguard 44447, Desiccated Magus 44315, Desiccated Spearman 44316, Opengut Behemoth 44562
UPDATE `creature_template` SET `flags_extra`=`flags_extra`|0x400 WHERE `entry` IN (44328,44326,44447,44315,44316,44562);
-- Second battle: Andorhal Defender 44448, Deathguard War-Captain 44449, Andorhal Force-Commander 44450, Lesser Val'kyr 45239, Forsaken Trooper 45240, Forsaken Trooper 45242, Provincial Minuteman 44944, Opengut Behemoth 44946, Frightened Provincial Minuteman 45101, Forsaken Trooper 45061, Andorhal Deathguard 44331, Andorhal Defender 44332
UPDATE `creature_template` SET `flags_extra`=`flags_extra`|0x400 WHERE `entry` IN (44448,44449,44450,45239,45240,45242,44944,44946,45101,45061,44331,44332);

-- 2. Second battle: our spawns go to phase 317 (Stickbone Berserkers to phase 314)
UPDATE `creature` SET `PhaseId`=317 WHERE `map`=0 AND `zoneId`=28 AND `id` IN (44447,44448,44449,44450,45239,45240,45242,45235,44944,44946,44955,45101,45061,44331,44332) AND `guid` NOT BETWEEN 735401343 AND 735401523;
UPDATE `creature` SET `PhaseId`=314 WHERE `map`=0 AND `zoneId`=28 AND `id`=44329;

-- 3. First battle: our 31 scattered copies make way for TDB 8.3.7's 181 spawns of the same entries (phase 314)
--    (Desiccated Magus 44315 40, Desiccated Spearman 44316 35, Opengut Behemoth 44562 32, Andorhal Deathguard 44326 28, Andorhal Defender 44328 28, Andorhal Deathguard 44447 18)
DELETE FROM `spawn_group` WHERE `spawnType`=0 AND `spawnId` IN (212312,212328,212349,212361,212464,212476,212516,212531,212536,212539,212543,212548,212549,212550,212553,212565,212624,212689,212690,212691,212807,212830,213074,213088,213094,213095,213114,213118,213119,213127,213170);
DELETE FROM `creature_addon` WHERE `guid` IN (212312,212328,212349,212361,212464,212476,212516,212531,212536,212539,212543,212548,212549,212550,212553,212565,212624,212689,212690,212691,212807,212830,213074,213088,213094,213095,213114,213118,213119,213127,213170);
DELETE FROM `creature` WHERE `guid` IN (212312,212328,212349,212361,212464,212476,212516,212531,212536,212539,212543,212548,212549,212550,212553,212565,212624,212689,212690,212691,212807,212830,213074,213088,213094,213095,213114,213118,213119,213127,213170);
DELETE FROM `spawn_group` WHERE `spawnType`=0 AND `spawnId` BETWEEN 735401343 AND 735401523;
DELETE FROM `creature_addon` WHERE `guid` BETWEEN 735401343 AND 735401523;
DELETE FROM `creature` WHERE `guid` BETWEEN 735401343 AND 735401523;
-- Quest-objective respawn group, as TDB 8.3.7 has it for these two entries

-- 4. Phases for Western Plaguelands (zone 28)
DELETE FROM `phase_area` WHERE `AreaId`=28 AND `PhaseId` IN (169,314,317);
DELETE FROM `conditions` WHERE `SourceTypeOrReferenceId`=26 AND `SourceGroup` IN (314,317) AND `SourceEntry`=28;

-- 5. Fight starters (out of combat, every 2-4 s: attack the closest enemy soldier or Scourge within 5-10 yards;
--    phases keep each battle to itself). The Scourge and the Forsaken answer once attacked.
DELETE FROM `smart_scripts` WHERE `source_type`=0 AND `entryorguid` IN (44328,44326,44447,44332,44448,44944) AND `id` BETWEEN 20 AND 29;
